def first_uniq_char(s):
    n = len(s)
    for i in range(n):
        count = 0
        for j in range(n):                                     # rescans the whole string for every character
            if s[j] == s[i]:
                count += 1
        if count == 1:
            return i
    return -1


if __name__ == "__main__":
    s = "loveleetcode"
    print(first_uniq_char(s))

