public class Main {
    int firstUniqChar(String s) {
        int n = s.length();
        for (int i = 0; i < n; i++) {
            int count = 0;
            for (int j = 0; j < n; j++) {                             // rescans the whole string for every character
                if (s.charAt(j) == s.charAt(i)) count++;
            }
            if (count == 1) return i;
        }
        return -1;
    }

    public static void main(String[] args) {
        String s = "loveleetcode";
        Main solution = new Main();
        System.out.println(solution.firstUniqChar(s));
    }
}

