int firstUniqChar(string s) {
    unordered_map<char, int> counts;
    for (char ch : s) counts[ch]++;                                  // tally every character once
    for (int i = 0; i < (int)s.size(); i++) {
        if (counts[s[i]] == 1) return i;
    }
    return -1;
}

